// Receive webhook + validate + stamp attribution + resolve location
const url = "https://chvthkqmwxrskkegwkuo.supabase.co/functions/v1/lead-capture";
const payload = {
  ghl_contact_id: "{{contact.id}}", ghl_opportunity_id: "{{opportunity.id}}",
  ghl_appointment_id: "{{appointment.id}}", pipeline_id: "{{opportunity.pipeline_id}}",
  new_pipeline_stage_id: "{{opportunity.stage_id}}", appointment_status: "{{appointment.status}}",
  monetary_value: Number("{{opportunity.monetary_value}}") || 0, source: "{{contact.source}}"
};
let lastErr;
for (let attempt = 1; attempt <= 3; attempt++) {
  try {
    const res = await fetch(url, { method: "POST", headers: {"Content-Type":"application/json"}, body: JSON.stringify(payload) });
    if (res.ok) return { success: true, attempt: attempt, status: res.status };
    lastErr = "HTTP " + res.status + ": " + (await res.text());
  } catch (e) { lastErr = (e && e.message) ? e.message : String(e); }
}
return { success: false, error: lastErr };
